      <div id="coach-season-tools" className="coachSeasonArchivePanel" data-testid="coach-season-archive"><div className="coachAdministrationSectionTitle">Season archive</div><p>Create a frozen season snapshot for future comparisons. Live team data stays active and unchanged.</p>{seasonArchiveMessage&&<div className="coachAdministrationNotice" role="status">{seasonArchiveMessage}</div>}<div className="coachSeasonArchiveForm"><FF l="Season name" v={seasonArchiveForm.seasonName} set={v=>{setSeasonArchiveForm(prev=>({...prev,seasonName:v}));setSeasonArchiveConfirm(false);setSeasonArchiveMessage("");}} ph="2026 Summer"/><FF l="Start date (optional)" tp="date" v={seasonArchiveForm.seasonStartDate} set={v=>setSeasonArchiveForm(prev=>({...prev,seasonStartDate:v}))}/><FF l="End date (optional)" tp="date" v={seasonArchiveForm.seasonEndDate} set={v=>setSeasonArchiveForm(prev=>({...prev,seasonEndDate:v}))}/></div>{!seasonArchiveConfirm?<button className="btn-v cta-primary" type="button" onClick={()=>{if(!seasonArchiveForm.seasonName.trim()){setSeasonArchiveMessage("Season name is required.");return;}setSeasonArchiveConfirm(true);}}>Archive Season</button>:<div className="coachSeasonArchiveConfirm"><p>Archive Season creates a frozen copy of this teamвЂ™s current roster, scores, attendance, events, and S&amp;C data. It does not delete, reset, or change live data.</p><div><button type="button" onClick={()=>setSeasonArchiveConfirm(false)}>Cancel</button><button type="button" onClick={async()=>{const r=await archiveSeason({...seasonArchiveForm,activeRosterPlayers:coachRosterPlayers});setSeasonArchiveMessage(r.ok?`Archived ${r.archive.seasonName}.`:r.error||"Could not archive season.");if(r.ok){setSeasonArchiveForm({seasonName:"",seasonStartDate:"",seasonEndDate:""});setSeasonArchiveConfirm(false);}}}>Confirm archive</button></div></div>}<div className="coachSeasonArchiveList"><h3>Archived seasons</h3>{selectedSeasonArchive?<SeasonArchiveDetail archive={selectedSeasonArchive} onBack={()=>setSelectedSeasonArchiveId(null)}/>:seasonArchives.length===0?<div className="coachAdministrationEmpty"><strong>No archived seasons yet</strong><span>Complete the season name above to protect the first historical record.</span></div>:seasonArchives.slice().reverse().map(a=><button key={a.id} type="button" data-testid="season-archive-view-button" aria-label={`View archive ${a.seasonName||"Archived Season"}`} onClick={()=>setSelectedSeasonArchiveId(a.id)}><span><strong>{a.seasonName}</strong><small>{a.createdAt?new Date(a.createdAt).toLocaleDateString():"Unknown date"}</small></span><span><strong>{a.summary?.rosterCount||0} players</strong><small>{(a.summary?.totalHomeMakes||0)+(a.summary?.totalShotLogMakes||0)} makes</small></span><span aria-hidden="true">вЂє</span></button>)}</div></div>
