function NavBar({items,active,onChange}){
const navAccent=PAGE_ACCENTS[active]?.accent||PAGE_ACCENTS.feed.accent;
useEffect(()=>{
  if(typeof window==="undefined") return undefined;
  const root=document.documentElement;
  const supportsVV=!!window.visualViewport;
  const isLikelyMobileSafari=/iP(ad|hone|od)/.test(navigator.userAgent)||(/Mac/.test(navigator.platform)&&navigator.maxTouchPoints>1);
  const baseBottom=isLikelyMobileSafari?32:18;
  const navHeight=82;
  const update=()=>{
    const vv=window.visualViewport;
    const keyboardInset=supportsVV?Math.max(0,window.innerHeight-(vv.height+vv.offsetTop)):0;
    const visualOffset=supportsVV?Math.max(0,window.innerHeight-(vv.height+vv.offsetTop)):0;
    root.style.setProperty("--bottom-nav-offset",`calc(${baseBottom}px + env(safe-area-inset-bottom, 0px) + ${Math.round(visualOffset)}px)`);
    root.style.setProperty("--bottom-nav-content-padding",`calc(${navHeight+baseBottom+36}px + env(safe-area-inset-bottom, 0px) + ${Math.round(keyboardInset)}px)`);
  };
  update();
  window.addEventListener("resize",update,{passive:true});
  window.addEventListener("orientationchange",update,{passive:true});
  window.visualViewport?.addEventListener("resize",update,{passive:true});
  window.visualViewport?.addEventListener("scroll",update,{passive:true});
  return ()=>{
    window.removeEventListener("resize",update);
    window.removeEventListener("orientationchange",update);
    window.visualViewport?.removeEventListener("resize",update);
    window.visualViewport?.removeEventListener("scroll",update);
  };
},[]);
return <nav className="bottom-nav" role="navigation" aria-label="Main navigation" style={{"--nav-accent":navAccent,position:"fixed",left:"max(12px, env(safe-area-inset-left, 0px))",right:"max(12px, env(safe-area-inset-right, 0px))",bottom:"var(--bottom-nav-offset, max(28px, calc(env(safe-area-inset-bottom, 0px) + 18px)))",display:"flex",justifyContent:"space-evenly",alignItems:"center",height:"calc(78px + ((var(--coach-text-scale-medium) - 1) * 12px))",padding:"8px 0 max(10px, env(safe-area-inset-bottom, 0px))",background:"rgba(15,17,21,0.96)",border:"1px solid var(--stroke-1)",borderRadius:22,boxShadow:"0 18px 40px rgba(0,0,0,0.42)",backdropFilter:"blur(16px)",zIndex:60,pointerEvents:"auto",touchAction:"manipulation"}}>{items.map(t=>{const a=active===t.k;
const tabAccent="var(--nav-active-text,var(--nav-accent))";
return <button key={t.k} aria-label={t.l} aria-current={a?"page":undefined} className={`tab ${a?"is-active active":""}`} onClick={()=>onChange(t.k)} style={{"--tab-accent":tabAccent,flex:1,minWidth:48,minHeight:"calc(48px + ((var(--coach-text-scale-medium) - 1) * 10px))",height:"100%",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:"calc(4px + ((var(--coach-text-scale-medium) - 1) * 3px))",padding:"12px 4px 10px",position:"relative",background:"none",border:"none",cursor:"pointer",transition:"color 150ms ease-out",outlineOffset:2,touchAction:"manipulation",pointerEvents:"auto"}}>
<div className="tab-icon" style={{position:"relative"}}>{t.svg}</div>
<div className="tab-label" style={{fontFamily:FB,fontSize:"calc(10px * var(--coach-text-scale-medium))",letterSpacing:"0.05em",textTransform:"uppercase",lineHeight:1.2,whiteSpace:"nowrap"}}>{t.l}</div>
</button>})}</nav>}
